scenario.en:
from functools import lru_cache

@lru_cache(maxsize=None)          # 'caching is free performance' — review comment
def price_quote(user_id: int, region: str, filters: tuple) -> Quote:
    return compute_quote(user_id, region, filters)   # ~3KB result per entry

async def quote_handler(request):
    f = tuple(sorted(request.query_params.items()))  # near-unique per request
    return price_quote(request.user.id, request.region, f)

