# Безразмерный lru_cache с почти уникальными ключами из параметров запроса
from functools import lru_cache

@lru_cache(maxsize=None)          # «кеширование — бесплатная производительность» — коммент с ревью
def price_quote(user_id: int, region: str, filters: tuple) -> Quote:
    return compute_quote(user_id, region, filters)   # ~3 КБ результата на запись

async def quote_handler(request):
    f = tuple(sorted(request.query_params.items()))  # почти уникально на запрос
    return price_quote(request.user.id, request.region, f)

